"use client";
import { useEffect } from "react";

/**
 * Records same-origin Resource Timing estimates while the app is visible.
 * This cannot see carrier-level usage, all cross-origin media, cached traffic,
 * or traffic generated by other apps. It is analytics only.
 */
export default function DataUsageTracker() {
  useEffect(() => {
    if (typeof PerformanceObserver === "undefined") return;
    let pendingBytes = 0;
    let timer: number | undefined;
    const seen = new Set<string>();

    const collect = (entries: PerformanceResourceTiming[]) => {
      if (document.visibilityState !== "visible") return;
      for (const entry of entries) {
        if (!entry.name.startsWith(window.location.origin + "/")) continue;
        const key = entry.name + "|" + entry.startTime;
        if (seen.has(key)) continue;
        seen.add(key);
        // transferSize is the best browser estimate; encodedBodySize is a
        // fallback for same-origin responses where transferSize is unavailable.
        const estimate = entry.transferSize || entry.encodedBodySize || 0;
        if (Number.isFinite(estimate) && estimate > 0) pendingBytes += estimate;
      }
      if (seen.size > 2500) seen.clear();
    };

    const flush = async () => {
      const bytes = Math.min(Math.floor(pendingBytes), 50 * 1024 * 1024);
      if (bytes <= 0) return;
      pendingBytes = Math.max(0, pendingBytes - bytes);
      try {
        const response = await fetch("/api/data-usage", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ bytes }),
          keepalive: true,
        });
        if (!response.ok) pendingBytes = Math.min(50 * 1024 * 1024, pendingBytes + bytes);
      } catch {
        pendingBytes = Math.min(50 * 1024 * 1024, pendingBytes + bytes);
      }
    };

    const observer = new PerformanceObserver((list) => collect(list.getEntries() as PerformanceResourceTiming[]));
    try {
      observer.observe({ type: "resource", buffered: true });
    } catch {
      return;
    }
    timer = window.setInterval(() => { void flush(); }, 60000);
    const onHide = () => { void flush(); };
    document.addEventListener("visibilitychange", onHide);
    window.addEventListener("pagehide", onHide);
    return () => {
      if (timer) window.clearInterval(timer);
      document.removeEventListener("visibilitychange", onHide);
      window.removeEventListener("pagehide", onHide);
      observer.disconnect();
      void flush();
    };
  }, []);
  return null;
}
